// Benchmark suite: real measured values only. Every number written by
// run_bench comes from a stopwatch (std::chrono steady_clock) or from
// getrusage(RUSAGE_SELF).ru_maxrss — never from a model.
//
// Methodology (docs/benchmark.md, generated by scripts/render_bench.py):
//   - warmup prompts run first and are discarded;
//   - per prompt: prefill of the whole prompt (timed = TTFT), then
//     greedy decode of max_new_tokens; the decode rate counts only the
//     decode window (total - prefill) over max_new_tokens tokens;
//   - tokens_per_s_decode and ttft_s are medians over bench.prompts;
//   - per_prompt_ms is the full generate call (prefill + decode);
//   - peak RSS is the process lifetime peak (Linux reports KiB; the
//     loader inflates it — documented caveat);
//   - ppl (--holdout): mean NLL over all predicted tokens on
//     non-overlapping max_seq windows of the frozen holdout, fp32 path
//     cross-checked against the NumPy oracle by the golden tests.

#include "bench/bench.h"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <dirent.h>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <sys/resource.h>

#include "kernels/kernels.h"
#include "model/model_def.h"
#include "model/transformer.h"
#include "tokenizer/bpe.h"

namespace heph {

namespace {

double now_s() {
    return std::chrono::duration<double>(
               std::chrono::steady_clock::now().time_since_epoch())
        .count();
}

double median(std::vector<double> v) {
    if (v.empty()) return 0.0;
    std::sort(v.begin(), v.end());
    const size_t n = v.size();
    if (n % 2 == 1) return v[n / 2];
    return 0.5 * (v[n / 2 - 1] + v[n / 2]);
}

std::vector<const float*> build_layer_weights(const SafetensorsFile& f,
                                              int n_layer) {
    static const char* kOrder[9] = {
        "attn_norm.weight", "attn.wq.weight", "attn.wk.weight",
        "attn.wv.weight",   "attn.wo.weight", "ffn_norm.weight",
        "ffn.w_gate.weight", "ffn.w_up.weight", "ffn.w_down.weight",
    };
    std::vector<const float*> lw;
    lw.reserve(static_cast<size_t>(n_layer) * 9);
    for (int l = 0; l < n_layer; ++l)
        for (const char* suffix : kOrder)
            lw.push_back(f.data("layer." + std::to_string(l) + "." + suffix));
    return lw;
}

}  // namespace

double peak_rss_mb() {
    rusage usage;
    if (getrusage(RUSAGE_SELF, &usage) != 0)
        throw std::runtime_error("getrusage failed");
    // Linux reports ru_maxrss in KiB; convert to MB.
    return static_cast<double>(usage.ru_maxrss) / 1024.0;
}

PromptSource load_bench_prompts(const std::string& path, int n) {
    std::ifstream fh(path);
    if (!fh) throw std::runtime_error("cannot open prompts file: " + path);
    PromptSource src;
    std::string line;
    while (std::getline(fh, line)) {
        if (!line.empty() && line[0] != '#') src.lines.push_back(line);
    }
    if (src.lines.empty())
        throw std::runtime_error("prompts file has no usable lines: " + path);
    if (static_cast<int>(src.lines.size()) < n) {
        // cycle to reach n prompts (deterministic order)
        const auto base = src.lines;
        size_t i = 0;
        while (static_cast<int>(src.lines.size()) < n) {
            src.lines.push_back(base[i % base.size()]);
            ++i;
        }
    }
    src.lines.resize(static_cast<size_t>(n));
    return src;
}

BenchResult run_bench(const Manifest& manifest, const std::string& weights_path,
                      const std::string& tokenizer_dir, QuantMode mode,
                      const std::string& prompts_file, int n_prompts,
                      int warmup, int max_new_tokens,
                      const std::string& holdout_dir) {
    BpeTokenizer tok;
    tok.load(tokenizer_dir);
    SafetensorsFile weights(weights_path);
    Transformer tf(manifest, weights.data("embedding.weight"),
                   build_layer_weights(weights, manifest.n_layer),
                   weights.data("final_norm.weight"));
    if (mode != QuantMode::Fp32) tf.set_weight_mode(mode, 128);

    // the loop runs warmup + n_prompts prompts: load that many
    const PromptSource prompts =
        load_bench_prompts(prompts_file, warmup + n_prompts);

    BenchResult result;
    result.mode = quant_mode_name(mode);
    std::vector<double> rates, ttfts;

    const int total_prompts = warmup + n_prompts;
    for (int p = 0; p < total_prompts; ++p) {
        const std::vector<int> ids = tok.encode(prompts.lines[static_cast<size_t>(p)]);
        if (ids.empty()) throw std::runtime_error("bench prompt tokenized empty");
        tf.reset_cache();
        const double t0 = now_s();
        tf.logits_last(ids, 0);  // prefill; last_logits() now holds the
                                 // distribution for the first new token
        int next = static_cast<int>(
            std::max_element(tf.last_logits(), tf.last_logits() + tf.vocab()) -
            tf.last_logits());
        const double ttft = now_s() - t0;

        const double t1 = now_s();
        // decode the remaining max_new_tokens - 1 greedily (the first
        // came from the prefill argmax)
        tf.greedy_generate(std::vector<int>{next}, max_new_tokens - 1, -1);
        const double decode = now_s() - t1;
        const double total = ttft + decode;

        if (p >= warmup) {
            rates.push_back(static_cast<double>(max_new_tokens) / decode);
            ttfts.push_back(ttft);
            result.per_prompt_ms.push_back(total * 1000.0);
        }
    }
    result.tokens_per_s_decode = median(rates);
    result.ttft_s = median(ttfts);
    result.peak_rss_mb = peak_rss_mb();

    if (!holdout_dir.empty()) {
        // frozen PROMETHEUS-NS holdout: every *.txt file, sorted
        std::vector<std::string> files;
        if (DIR* dir = opendir(holdout_dir.c_str())) {
            while (dirent* ent = readdir(dir)) {
                const std::string name = ent->d_name;
                if (name.size() > 4 && name.substr(name.size() - 4) == ".txt")
                    files.push_back(holdout_dir + "/" + name);
            }
            closedir(dir);
        }
        std::sort(files.begin(), files.end());
        if (files.empty())
            throw std::runtime_error("holdout dir has no .txt files: " + holdout_dir);

        double nll_sum = 0.0;
        long predicted = 0;
        for (const std::string& path : files) {
            std::ifstream fh(path);
            if (!fh) throw std::runtime_error("cannot open holdout file: " + path);
            std::stringstream ss;
            ss << fh.rdbuf();
            const std::vector<int> ids = tok.encode(ss.str());
            // non-overlapping max_seq windows; within a window every
            // position p >= 1 is a predicted token
            for (size_t w = 0; w < ids.size(); w += static_cast<size_t>(manifest.max_seq)) {
                const size_t lo = w;
                const size_t hi = std::min(ids.size(),
                                           w + static_cast<size_t>(manifest.max_seq));
                if (hi - lo < 2) break;
                tf.reset_cache();
                tf.logits_last(std::vector<int>{ids[lo]}, 0);
                for (size_t p = lo + 1; p < hi; ++p) {
                    // NLL of ids[p] under the current distribution
                    const float* lg = tf.last_logits();
                    float mx = lg[0];
                    for (int i = 1; i < manifest.vocab; ++i)
                        mx = std::max(mx, lg[i]);
                    double z = 0.0;
                    for (int i = 0; i < manifest.vocab; ++i)
                        z += std::exp(static_cast<double>(lg[i] - mx));
                    // NLL = -(lg[t] - mx) + log(z)  (log-sum-exp trapezoid)
                    nll_sum += -(static_cast<double>(lg[ids[p]]) - mx) +
                               std::log(z);
                    ++predicted;
                    // feed the token and advance the cache
                    tf.logits_last(std::vector<int>{ids[p]}, tf.cache_len());
                }
            }
        }
        if (predicted > 0) {
            result.has_ppl = true;
            result.ppl = std::exp(nll_sum / static_cast<double>(predicted));
            result.ppl_tokens = predicted;
        }
    }
    return result;
}

void write_bench_json(const std::string& path, const BenchResult& r) {
    std::ostringstream out;
    out << "{\n";
    out << "  \"mode\": \"" << r.mode << "\",\n";
    out << "  \"tokens_per_s_decode\": " << r.tokens_per_s_decode << ",\n";
    out << "  \"ttft_s\": " << r.ttft_s << ",\n";
    out << "  \"peak_rss_mb\": " << r.peak_rss_mb << ",\n";
    out << "  \"per_prompt_ms\": [";
    for (size_t i = 0; i < r.per_prompt_ms.size(); ++i) {
        if (i) out << ", ";
        out << r.per_prompt_ms[i];
    }
    out << "]";
    if (r.has_ppl) {
        out << ",\n  \"ppl\": " << r.ppl << ",\n";
        out << "  \"ppl_tokens\": " << r.ppl_tokens << "\n";
    } else {
        out << "\n";
    }
    out << "}\n";
    std::ofstream fh(path);
    if (!fh) throw std::runtime_error("cannot write bench json: " + path);
    fh << out.str();
}

}  // namespace heph
